import React, { useState, useMemo } from 'react';
import {
  View,
  Text,
  Pressable,
  ScrollView,
  Switch,
  Alert,
  StyleSheet,
} from 'react-native';
import { useTheme } from '@/theme';
import { createStyles } from '@/theme';
import { useRouter } from 'expo-router';
import { Button } from '@/components/Button';
import { Card } from '@/components/Card';
import { Badge } from '@/components/Badge';
import { TextField } from '@/components/TextField';
import { EmptyState } from '@/components/EmptyState';
import { SafeAreaView } from 'react-native-safe-area-context';
import * as Haptics from 'expo-haptics';
import { Ionicons } from '@expo/vector-icons';

type Task = {
  id: string;
  text: string;
  priority: 'Low' | 'Med' | 'High';
  completed: boolean;
};

const TodoBoardScreen = () => {
  const theme = useTheme();
  const router = useRouter();
  const s = useStyles();

  // Static user info
  const userName = 'Alex Morgan';

  // Date & greeting
  const now = new Date();
  const dateString = now.toLocaleDateString('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

  // Task state
  const [tasks, setTasks] = useState<Task[]>([
    { id: '1', text: 'Finish onboarding prototype', priority: 'High', completed: false },
    { id: '2', text: 'Design new onboarding flow', priority: 'Med', completed: true },
    { id: '3', text: 'Review user feedback', priority: 'Low', completed: false },
    { id: '4', text: 'Plan sprint retros', priority: 'High', completed: false },
    { id: '5', text: 'Update documentation', priority: 'Low', completed: true },
  ]);

  // Search & UI state
  const [searchQuery, setSearchQuery] = useState('');
  const [showSearchOverlay, setShowSearchOverlay] = useState(false);
  const [newTaskText, setNewTaskText] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Med' | 'High'>('Low');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editText, setEditText] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  // Stats
  const total = tasks.length;
  const completed = tasks.filter((t) => t.completed).length;
  const progressPercent = total ? completed / total : 0;

  // Filtered tasks
  const filteredTasks = useMemo(() => {
    if (!searchQuery) return tasks;
    const q = searchQuery.toLowerCase();
    return tasks.filter((t) => t.text.toLowerCase().includes(q));
  }, [tasks, searchQuery]);

  // Helpers
  const triggerHaptic = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
  };

  // CRUD actions
  const handleAdd = async () => {
    if (!newTaskText.trim()) return;
    setIsAdding(true);
    await new Promise((resolve) => setTimeout(resolve, 200));
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      text: newTaskText.trim(),
      priority: newTaskPriority,
      completed: false,
    };
    setTasks((prev) => [newTask, ...prev]);
    setNewTaskText('');
    setNewTaskPriority('Low');
    setIsAdding(false);
    triggerHaptic();
  };

  const toggleTask = (id: string) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t))
    );
    triggerHaptic();
  };

  const deleteTask = (id: string) => {
    Alert.alert('Delete Task', 'Are you sure you want to delete this task?', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: () => {
          setTasks((prev) => prev.filter((t) => t.id !== id));
          triggerHaptic();
        },
      },
    ]);
  };

  const startEdit = (task: Task) => {
    setEditingId(task.id);
    setEditText(task.text);
  };

  const saveEdit = (id: string) => {
    setTasks((prev) =>
      prev.map((t) =>
        t.id === id ? { ...t, text: editText.trim() } : t
      )
    );
    setEditingId(null);
    triggerHaptic();
  };

  const clearCompleted = () => {
    Alert.alert('Clear Completed', 'Remove all completed tasks?', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Clear',
        style: 'destructive',
        onPress: () => {
          setTasks((prev) => prev.filter((t) => !t.completed));
          triggerHaptic();
        },
      },
    ]);
  };

  // Render each task row
  const renderTask = (task: Task) => {
    const isEditing = editingId === task.id;
    const priorityVariant =
      task.priority === 'Low'
        ? 'success'
        : task.priority === 'Med'
        ? 'warning'
        : 'danger';

    return (
      <Card key={task.id} style={s.taskCard}>
        <View style={s.taskRow}>
          <Switch
            value={task.completed}
            onValueChange={() => toggleTask(task.id)}
            thumbColor={
              task.completed ? theme.colors.success : theme.colors.textMuted
            }
            trackColor={{
              false: theme.colors.surfaceAlt,
              true: theme.colors.success + '40',
            }}
          />
          <View style={s.taskContent}>
            {isEditing ? (
              <TextField
                value={editText}
                onChangeText={setEditText}
                placeholder="Task title"
                autoFocus
                returnKeyType="done"
                onSubmitEditing={() => saveEdit(task.id)}
                style={s.editField}
              />
            ) : (
              <Pressable onPress={() => startEdit(task)} style={s.titlePressable}>
                <Text
                  style={[
                    s.taskTitle,
                    task.completed && s.completedTitle,
                  ]}
                >
                  {task.text}
                </Text>
              </Pressable>
            )}
            <View style={s.badgesRow}>
              <Badge
                label={task.priority}
                variant={priorityVariant}
                size="sm"
              />
            </View>
          </View>
          <Button
            icon="trash-outline"
            variant="ghost"
            size="md"
            onPress={() => deleteTask(task.id)}
            style={s.deleteButton}
          />
        </View>
      </Card>
    );
  };

  // Priority selector buttons for quick-add
  const PriorityButton = ({
    value,
    label,
    current,
    onSelect,
  }: {
    value: 'Low' | 'Med' | 'High';
    label: string;
    current: 'Low' | 'Med' | 'High';
    onSelect: (v: 'Low' | 'Med' | 'High') => void;
  }) => {
    const isActive = current === value;
    return (
      <Button
        variant={isActive ? 'primary' : 'secondary'}
        size="md"
        onPress={() => onSelect(value)}
        style={s.priorityBtn}
      >
        {label}
      </Button>
    );
  };

  return (
    <SafeAreaView style={s.container} edges={['top', 'left', 'right']}>
      {/* Header */}
      <View style={s.header}>
        <View>
          <Text style={s.greeting}>Hi {userName}</Text>
          <Text style={s.date}>{dateString}</Text>
        </View>
        <View style={s.headerActions}>
          <Button
            icon="search-outline"
            variant="ghost"
            onPress={() => setShowSearchOverlay(true)}
          />
          <Button
            icon="trash-outline"
            variant="ghost"
            onPress={clearCompleted}
          />
        </View>
      </View>

      {/* Progress Bar */}
      <View style={s.progressContainer}>
        <View style={s.progressLabelRow}>
          <Text style={s.progressText}>
            Progress: {completed} of {total} tasks
          </Text>
          <Text style={s.progressPercent}>
            {Math.round(progressPercent * 100)}%
          </Text>
        </View>
        <View style={s.progressTrack}>
          <View
            style={[
              s.progressFill,
              { width: `${progressPercent * 100}%` },
            ]}
          />
        </View>
      </View>

      {/* Search overlay */}
      {showSearchOverlay && (
        <View style={s.searchOverlay}>
          <TextField
            placeholder="Search tasks..."
            value={searchQuery}
            onChangeText={setSearchQuery}
            autoFocus
            style={s.searchInput}
          />
          <Button
            variant="ghost"
            onPress={() => {
              setShowSearchOverlay(false);
              setSearchQuery('');
            }}
          >
            Cancel
          </Button>
        </View>
      )}

      {/* Task List */}
      <ScrollView
        style={s.list}
        contentContainerStyle={s.listContent}
        keyboardShouldPersistTaps="handled"
      >
        {filteredTasks.length === 0 ? (
          <EmptyState
            icon="list-outline"
            title="All clear!"
            description="No tasks yet. Add one to get started."
            actionLabel="Add Task"
            onAction={() => {
              // Scroll to quick-add bar (optional)
            }}
          />
        ) : (
          filteredTasks.map(renderTask)
        )}
        <View style={s.spacer} />
      </ScrollView>

      {/* Quick-add bar */}
      <View style={s.quickAddBar}>
        <TextField
          placeholder="Add a new task..."
          value={newTaskText}
          onChangeText={setNewTaskText}
          style={s.quickAddInput}
          returnKeyType="done"
          onSubmitEditing={handleAdd}
        />
        <View style={s.prioritySelector}>
          <PriorityButton
            value="Low"
            label="Low"
            current={newTaskPriority}
            onSelect={setNewTaskPriority}
          />
          <PriorityButton
            value="Med"
            label="Medium"
            current={newTaskPriority}
            onSelect={setNewTaskPriority}
          />
          <PriorityButton
            value="High"
            label="High"
            current={newTaskPriority}
            onSelect={setNewTaskPriority}
          />
        </View>
        <Button
          icon="add"
          loading={isAdding}
          onPress={handleAdd}
          style={s.addButton}
          disabled={!newTaskText.trim()}
        />
      </View>
    </SafeAreaView>
  );
};

