import React from 'react';
import { View, Text } from 'react-native';
import { useTheme } from '@/theme';
import { createStyles } from '@/theme';

interface BadgeProps {
  label: string;
  variant?: 'accent' | 'success' | 'warning' | 'danger' | 'primary';
  size?: 'sm' | 'md';
}

const useStyles = createStyles((t) => ({
  container: {
    paddingHorizontal: t.spacing.sm,
    paddingVertical: t.spacing.xs,
    borderRadius: t.radius.pill,
    alignSelf: 'flex-start',
    alignItems: 'center',
    justifyContent: 'center',
  },
  sm: { minHeight: 20 },
  md: { minHeight: 28 },
  accent: { backgroundColor: t.colors.accent },
  success: { backgroundColor: t.colors.success },
  warning: { backgroundColor: t.colors.warning },
  danger: { backgroundColor: t.colors.danger },
  primary: { backgroundColor: t.colors.primary },
  text: {
    color: t.colors.onAccent,
    fontSize: 12,
    fontWeight: '600',
    letterSpacing: -0.3,
  },
}));

const Badge: React.FC<BadgeProps> = ({ label, variant = 'accent', size = 'sm' }) => {
  const s = useStyles();

  const variantStyle = (() => {
    switch (variant) {
      case 'success': return s.success;
      case 'warning': return s.warning;
      case 'danger': return s.danger;
      case 'primary': return s.primary;
      default: return s.accent;
    }
  })();

  const sizeStyle = size === 'sm' ? s.sm : s.md;

  return (
    <View style={[s.container, variantStyle, sizeStyle]}>
      <Text style={s.text}>{label}</Text>
    </View>
  );
};

export default Badge;

