import React, { forwardRef } from 'react';
import { Pressable, Text, ActivityIndicator, View, StyleSheet } from 'react-native';
import { useTheme } from '@/theme';
import { createStyles } from '@/theme';
import { Ionicons } from '@expo/vector-icons';

type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'destructive';
type ButtonSize = 'md' | 'lg';

interface ButtonProps {
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  disabled?: boolean;
  onPress?: () => void;
  children?: React.ReactNode;
  icon?: keyof typeof Ionicons.glyphMap;
  iconPosition?: 'left' | 'right';
}

const useStyles = createStyles((t) => ({
  base: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: t.radius.md,
    paddingHorizontal: t.spacing.md,
    minHeight: 52,
  },
  primary: { backgroundColor: t.colors.primary },
  secondary: {
    backgroundColor: t.colors.surface,
    borderWidth: 1,
    borderColor: t.colors.border,
  },
  ghost: { backgroundColor: 'transparent' },
  destructive: { backgroundColor: t.colors.danger },
  disabled: { opacity: 0.5 },
  loading: { opacity: 0.7 },
  text: {
    fontSize: 16,
    fontWeight: '600',
    lineHeight: 24,
    letterSpacing: -0.5,
  },
  primaryText: { color: t.colors.onPrimary },
  secondaryText: { color: t.colors.text },
  ghostText: { color: t.colors.text },
  destructiveText: { color: t.colors.onAccent },
  icon: { marginHorizontal: t.spacing.xs },
  leftIcon: { marginRight: t.spacing.xs },
  rightIcon: { marginLeft: t.spacing.xs },
  sizeLg: { minHeight: 56, paddingVertical: t.spacing.md },
}));

const Button = forwardRef<Pressable, ButtonProps>(({
  variant = 'primary',
  size = 'md',
  loading = false,
  disabled = false,
  onPress,
  children,
  icon,
  iconPosition = 'left',
}, ref) => {
  const theme = useTheme();
  const s = useStyles();

  const opacity = (loading || disabled) ? 0.5 : 0.9;
  const variantStyle =
    variant === 'primary' ? s.primary :
    variant === 'secondary' ? s.secondary :
    variant === 'ghost' ? s.ghost :
    variant === 'destructive' ? s.destructive : s.primary;

  const textStyle =
    variant === 'primary' ? s.primaryText :
    variant === 'secondary' ? s.secondaryText :
    variant === 'ghost' ? s.ghostText :
    variant === 'destructive' ? s.destructiveText : s.primaryText;

  const iconColor =
    variant === 'primary' ? theme.colors.onPrimary :
    variant === 'secondary' || variant === 'ghost' ? theme.colors.text :
    variant === 'destructive' ? theme.colors.onAccent : theme.colors.onPrimary;

  return (
    <Pressable
      ref={ref}
      style={[
        s.base,
        variantStyle,
        disabled && s.disabled,
        { opacity },
        size === 'lg' && s.sizeLg,
      ]}
      disabled={disabled || loading}
      onPress={onPress}
    >
      {loading && (
        <ActivityIndicator
          size="small"
          color={variant === 'primary' ? theme.colors.onPrimary : theme.colors.text}
          style={{ marginHorizontal: 8 }}
        />
      )}
      {!loading && icon && iconPosition === 'left' && (
        <Ionicons
          name={icon}
          size={20}
          color={iconColor}
          style={s.leftIcon}
        />
      )}
      {!loading && children && (
        <Text style={[s.text, textStyle]}>{children}</Text>
      )}
      {!loading && icon && iconPosition === 'right' && (
        <Ionicons
          name={icon}
          size={20}
          color={iconColor}
          style={s.rightIcon}
        />
      )}
    </Pressable>
  );
});

export default Button;

