import React from 'react';
import { Pressable, View, Text, Switch, StyleSheet } from "react-native";
import { useTheme } from '@/theme';
import { createStyles } from '@/theme';
import { Ionicons } from '@expo/vector-icons';
import Avatar from './Avatar';

type ListRowVariant = 'default' | 'checkbox';

interface ListRowProps {
  title: string;
  subtitle?: string;
  leadingIcon?: keyof typeof Ionicons.glyphMap;
  leadingAvatar?: string;
  trailing?: React.ReactNode;
  onPress?: () => void;
  onToggle?: (checked: boolean) => void;
  isCompleted?: boolean;
  disabled?: boolean;
  variant?: ListRowVariant;
}

const useStyles = createStyles((t) => ({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 56,
    paddingHorizontal: t.spacing.lg,
    backgroundColor: t.colors.surface,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: t.colors.border,
  },
  leading: {
    width: 32,
    height: 32,
    borderRadius: t.radius.sm,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: t.spacing.md,
  },
  content: { flex: 1 },
  title: {
    fontSize: 16,
    fontWeight: '600',
    color: t.colors.text,
    marginBottom: 2,
  },
  subtitle: {
    fontSize: 14,
    color: t.colors.textMuted,
  },
  trailing: { marginLeft: t.spacing.md },
  chevron: { marginLeft: t.spacing.xs },
  completedTitle: {
    textDecorationLine: 'line-through',
    color: t.colors.textMuted,
    opacity: 0.7,
  },
  completedSubtitle: {
    textDecorationLine: 'line-through',
    color: t.colors.textMuted,
    opacity: 0.6,
  },
}));

const ListRow: React.FC<ListRowProps> = ({
  title,
  subtitle,
  leadingIcon,
  leadingAvatar,
  trailing,
  onPress,
  onToggle,
  isCompleted = false,
  disabled = false,
}) => {
  const s = useStyles();
  const theme = useTheme();

  const handlePress = () => {
    if (onToggle !== undefined) {
      onToggle(!isCompleted);
    } else if (onPress) {
      onPress();
    }
  };

  let leadingElement: React.ReactNode = null;
  if (leadingAvatar) {
    leadingElement = <Avatar source={leadingAvatar} size={32} />;
  } else if (leadingIcon) {
    leadingElement = (
      <View
        style={[
          s.leading,
          { backgroundColor: isCompleted ? theme.colors.success + '20' : theme.colors.primary + '20' },
        ]}
      >
        <Ionicons
          name={leadingIcon}
          size={20}
          color={isCompleted ? theme.colors.success : theme.colors.primary}
        />
      </View>
    );
  }

  let finalTrailing = trailing;
  if (onToggle !== undefined) {
    finalTrailing = (
      <Switch
        value={isCompleted}
        onValueChange={onToggle}
        thumbColor={isCompleted ? theme.colors.success : theme.colors.textMuted}
        trackColor={{ false: theme.colors.surfaceAlt, true: theme.colors.success + '40' }}
      />
    );
  } else if (onPress) {
    finalTrailing = (
      <View style={s.chevron}>
        <Ionicons name="chevron-forward" size={20} color={theme.colors.textMuted} />
      </View>
    );
  }

  return (
    <Pressable
      style={({ pressed }) => [s.container, pressed && { opacity: 0.95 }]}
      onPress={handlePress}
      disabled={disabled}
    >
      {leadingElement}
      <View style={s.content}>
        <Text
          style={[s.title, isCompleted && s.completedTitle]}
          numberOfLines={1}
        >
          {title}
        </Text>
        {subtitle && (
          <Text
            style={[s.subtitle, isCompleted && s.completedSubtitle]}
            numberOfLines={1}
          >
            {subtitle}
          </Text>
        )}
      </View>
      {finalTrailing && <View style={s.trailing}>{finalTrailing}</View>}
    </Pressable>
  );
};

export default ListRow;

